CREATE OR REPLACE PROCEDURE aerospace_parts_inventory_2_db.core.log_stage_approval(IN stage_name VARCHAR(50), IN actor_name VARCHAR(100))
BEGIN
    INSERT INTO aerospace_parts_inventory_2_db.core.deployment_audit (audit_id, stage, action, actor, logged_at)
    VALUES (UNIX_TIMESTAMP(), stage_name, 'approved', actor_name, CURRENT_TIMESTAMP());
END;

CREATE OR REPLACE PROCEDURE aerospace_parts_inventory_2_db.core.update_task_status(IN task_id_in INTEGER, IN status_in VARCHAR(20))
BEGIN
    UPDATE aerospace_parts_inventory_2_db.core.story_tasks SET status = status_in WHERE task_id = task_id_in;
END;
